contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 donationAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (donationAmount)); require(donationAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= donationAmount);
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.donate{value: donationAmount}(); if (__ESBMC_reverted()) return;

        bool reverted;
        uint256 pot;
        uint256 p = c.winnersPot(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            pot = p;
            reverted = false;
        }

        assert(reverted || pot == address(c).balance / 2);
    }

    receive() external payable {}
}

