// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 donationAmount) internal {
        donationAmount = bound(donationAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= donationAmount);
        try c.OpenToThePublic() {} catch { return; }
        try c.donate{value: donationAmount}() {} catch { return; }
        bool reverted;
        uint256 pot;
        try c.winnersPot() returns (uint256 p) {
            pot = p;
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted || pot == address(c).balance / 2);
    }

    function testFuzz_run(uint256 donationAmount) public {
        _run(donationAmount);
    }

    receive() external payable {}
}
